CREATE OR ALTER TRIGGER dbo.trg_product_price_validate ON dbo.product_price INSTEAD OF UPDATE AS BEGIN SET NOCOUNT ON; IF UPDATE(Price) AND EXISTS(SELECT 1 FROM inserted i JOIN dbo.product_price p ON p.ProductID=i.ProductID WHERE i.Price<p.CostPrice) BEGIN INSERT dbo.price_rejection_log(ProductID,AttemptedPrice,CostPrice,AttemptedBy,Reason) SELECT i.ProductID,i.Price,p.CostPrice,ORIGINAL_LOGIN(),'Price is below cost' FROM inserted i JOIN dbo.product_price p ON p.ProductID=i.ProductID WHERE i.Price<p.CostPrice; THROW 51001,'Price update rejected: one or more prices are below cost.',1; END; UPDATE p SET ProductName=i.ProductName,CostPrice=i.CostPrice,Price=i.Price FROM dbo.product_price p JOIN inserted i ON i.ProductID=p.ProductID; END;
GO
CREATE OR ALTER TRIGGER dbo.trg_product_price_audit ON dbo.product_price AFTER UPDATE AS BEGIN SET NOCOUNT ON; INSERT dbo.price_audit(ProductID,OldPrice,NewPrice,ChangedBy,ChangedAt) SELECT i.ProductID,d.Price,i.Price,ORIGINAL_LOGIN(),SYSDATETIME() FROM inserted i JOIN deleted d ON d.ProductID=i.ProductID WHERE ISNULL(d.Price,-1)<>ISNULL(i.Price,-1); END;